     5	/** The confirmation by e-mail. */
     6	public final class EmailConfirmationChannel implements ConfirmationChannel {
     7	
     8	    static final String HOTEL_NAME = "Pousada Maré Alta";
     9	
    10	    private final EmailSender emailSender;
    11	
    12	    public EmailConfirmationChannel(EmailSender emailSender) {
    13	        this.emailSender = emailSender;
    14	    }
    15	
    16	    @Override
    17	    public void sendConfirmation(String guestName, String guestEmail, ReservationReceipt receipt) {
