    19	    }
    20	
    21	    private static String body(String guestName, ReservationReceipt receipt) {
    22	        return "Olá, " + guestName + "!\n\n"
    23	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
    24	                + receipt.text() + "\n"
    25	                + "Entrada a partir das 14h e saída até as 12h.\n"
    26	                + "Café da manhã das 7h às 10h, incluído na diária.\n"
    27	                + "Qualquer dúvida, fale com a recepção: (79) 3200-0000.\n"
    28	                + "Até breve!\n";
    29	    }
