     1	package hotel;
     2	
     3	import hotel.messages.EmailConfirmationChannel;
     4	import hotel.messages.EmailSender;
     5	import hotel.messages.SentMessages;
     6	import hotel.reports.OccupancyReport;
     7	import hotel.reports.RevenueReport;
     8	import hotel.reservations.PriceCalculator;
     9	import hotel.reservations.ReservationService;
    10	import hotel.reservations.ReservationStore;
    11	import hotel.rooms.Rooms;
    12	import hotel.web.HttpApi;
    13	import io.javalin.Javalin;
    14	
    15	/** Puts the inn's pieces together and runs the HTTP server. */
    16	public final class Hotel {
    17	
    18	    private final Javalin server;
    19	
    20	    public Hotel() {
    21	        Rooms rooms = new Rooms();
    22	        ReservationStore store = new ReservationStore();
    23	        SentMessages sentMessages = new SentMessages();
    24	        ReservationService reservations =
    25	                new ReservationService(rooms, store, new PriceCalculator(),
    26	                        new EmailConfirmationChannel(new EmailSender(sentMessages)));
    27	        HttpApi api = new HttpApi(
    28	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    29	        this.server = api.server();
    30	    }
    31	
    32	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    33	    public int start(int port) {
    34	        server.start(port);
    35	        return server.port();
    36	    }
    37	
    38	    public void stop() {
    39	        server.stop();
    40	    }
    41	
    42	    public static void main(String[] args) {
    43	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    44	        new Hotel().start(port);
    45	    }
    46	}
=== reservations/ReservationService.java
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.ConfirmationChannel;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final ConfirmationChannel confirmationChannel;
    16	
    17	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    18	            ConfirmationChannel confirmationChannel) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	        this.priceCalculator = priceCalculator;
    22	        this.confirmationChannel = confirmationChannel;
    23	    }
    24	
    25	    public synchronized Reservation create(NewReservation request) {
    26	        if (!request.checkOut().isAfter(request.checkIn())) {
    27	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    28	        }
    29	        if (request.guests() < 1) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    31	        }
    32	        Room room = rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new HotelException(
    34	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new HotelException(
    37	                    ErrorCode.CAPACITY_EXCEEDED,
    38	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    39	        }
    40	        boolean roomTaken = store.all().stream()
    41	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    42	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    43	        if (roomTaken) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    48	        Reservation reservation = new Reservation(store.nextId(), request, price);
    49	        store.save(reservation);
    50	        return reservation;
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    67	        confirmationChannel.sendConfirmation(reservation.guest().name(), reservation.guest().email(), receipt);
    68	        return reservation;
    69	    }
    70	
    71	    /**
    72	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    73	     * reservation was never paid, so nothing comes back).
    74	     */
    75	    public synchronized Reservation cancel(long reservationId) {
    76	        Reservation reservation = find(reservationId);
    77	        if (reservation.status() != ReservationStatus.PENDING
    78	                && reservation.status() != ReservationStatus.CONFIRMED) {
    79	            throw notAllowed(reservation, "cancel");
    80	        }
    81	        BigDecimal refund = switch (reservation.ratePlan()) {
    82	            case STANDARD -> reservation.amountPaid();
    83	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    84	        };
    85	        reservation.cancel(refund);
    86	        return reservation;
    87	    }
    88	
    89	    public synchronized Reservation checkIn(long reservationId) {
    90	        Reservation reservation = find(reservationId);
    91	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    92	            throw notAllowed(reservation, "check in");
    93	        }
    94	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    95	        return reservation;
    96	    }
    97	
    98	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
    99	    public synchronized ReservationReceipt checkOut(long reservationId) {
   100	        Reservation reservation = find(reservationId);
   101	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   102	            throw notAllowed(reservation, "check out");
   103	        }
   104	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   105	        return new ReservationReceipt(reservation, roomOf(reservation));
   106	    }
   107	
   108	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   109	    public ReservationReceipt receiptCopy(long reservationId) {
   110	        Reservation reservation = find(reservationId);
   111	        if (!reservation.isPaid()) {
   112	            throw notAllowed(reservation, "issue a receipt for");
   113	        }
   114	        return new ReservationReceipt(reservation, roomOf(reservation));
   115	    }
   116	
   117	    private Room roomOf(Reservation reservation) {
   118	        return rooms.find(reservation.roomNumber()).orElseThrow();
   119	    }
   120	
   121	    private static HotelException notAllowed(Reservation reservation, String operation) {
   122	        return new HotelException(
   123	                ErrorCode.OPERATION_NOT_ALLOWED,
   124	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   125	    }
   126	}

